"use strict";(globalThis.webpackChunkgrc||=[]).push([[12036],{88931(e){e.exports=JSON.parse('[{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio"],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2026agentrecall","slug":"bateman-2026-agentrecall-339d","title":"AgentRecall: Provenance and Rewind for Multi-Agent Workflows","authors":["K. Bateman","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Bateman_Keith_AgentRecall%20-%20keith%20bateman.pdf"},"_projectIds":["dtio","iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2025dtio","slug":"bateman-2025-dtio-e77d","title":"DTIO: Data Stack for AI-driven Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3733723.3733736","abstract":"HPC, Big Data Analytics, and Machine Learning have become in- creasingly intertwined as popular models such as LLMs and Diffusion Models have been driving discovery in scientific fields. However, each of these domains has its own storage infrastructure with unique I/O interfaces and storage systems, requiring feature sets that are often incompatible. Users with experience in one domain lack the expertise to change their applications to match the data stacks of the other domains, necessitating expensive conversions. There is a need for a transparent solution for the unification of disparate data stacks for the triple convergence of HPC, Big Data, and ML that can provide the required functionality while achieving higher performance. To better support converged HPC, Big Data, and ML workflows, this paper proposes DTIO, a scalable I/O runtime that unifies the disparate I/O stack for modern scientific ML workflows. DTIO utilizes a unique DataTask abstraction to express the move- ment of data, its ordering, and its dependencies on other data as a task. DTIO achieves a unification of scientific and ML workflows by utilizing intelligent mapping of interfaces, and automatically de- termines the best method to relate their unique semantics. DTIO\'s online translation with DataTask caching can improve performance by 49.6% compared to offline translation methods. DTIO also offers numerous optimizations, such as asynchronous I/O and aggregation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2025/bateman-2025-dtio-e77d.pdf"},"tags":["Task Systems","Data Stacks","Systems for AI Workflows"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025unifiedstack","slug":"bateman-2025-unified-data-stack-8de5","title":"A Unified Data Stack for AI Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"rajesh2025eris","slug":"rajesh-2025-eris-a1a8","title":"Eris: A Trace-Driven Gym for AI-Powered Cache Optimization in HPC","authors":["N. Rajesh","K. Bateman","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":["coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"ye2024viper","slug":"ye-2024-viper-0a1b","title":"Viper: A High-Performance I/O Framework for Transparently Updating, Storing, and Transferring Deep Neural Network Models","authors":["J. Ye","J. Cernuda","N. Rajesh","K. Bateman","O. Yildiz","T. Peterka","A. Nigmetov","D. Morozov","A. Kougkas","X.-H. Sun","B. Nicolae"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673070","abstract":"Scientific workflows increasingly need to train a DNN model in real-time during an experiment (e.g. using ground truth from a sim- ulation), while using it at the same time for inferences. Instead of sharing the same model instance, the training (producer) and infer- ence server (consumer) often use different model replicas that are kept synchronized. In addition to efficient I/O techniques to keep the model replica of the producer and consumer synchronized, there is another important trade-off: frequent model updates enhance infer- ence quality but may slow down training; infrequent updates may lead to less precise inference results. To address these challenges, we introduce Viper: a new I/O framework designed to determine a near- optimal checkpoint schedule and accelerate the delivery of the latest model updates. Viper builds an inference performance predictor to identify the optimal checkpoint schedule to balance the trade-off be- tween training slowdown and inference quality improvement. It also creates a memory-first model transfer engine to accelerate model delivery through direct memory-to-memory communication. Our experiments show that Viper can reduce the model update latency by \u2248 9x using the GPU-to-GPU data transfer engine and \u2248 3x using the DRAM-to-DRAM host data transfer. The checkpoint schedule obtained from Viper\'s predictor also demonstrates improved cumu- lative inference accuracy compared to the baseline of epoch-based solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b.pdf","slides":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b-slides.pptx"},"tags":["AI Workflows","Adaptive AI Model Checkpointing","Coupled Training and Inferences","Inferences During Partial Training","LABIOS"],"_projectIds":["deepio"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2024tunio","slug":"rajesh-2024-tunio-05a8","title":"TunIO: An AI-powered Framework for Optimizing HPC I/O","authors":["N. Rajesh","K. Bateman","S. Byna","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 38th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ipdps57955.2024.00050","abstract":"I/O operations are a known performance bottleneck of HPC applications. To achieve good performance, users often employ an iterative multistage tuning process to find an optimal I/O stack configuration. However, an I/O stack contains multiple layers, such as high-level I/O libraries, I/O middleware, and parallel file systems, and each layer has many parameters. These parameters and layers are entangled and influenced by each other. The tuning process is time-consuming and complex. In this work, we present TunIO, an AI- powered I/O tuning framework that implements several techniques to balance the tuning cost and performance gain, including tuning the high- impact parameters first. Furthermore, TunIO analyzes the application source code to extract its I/O kernel while retaining all statements necessary to perform I/O. It utilizes a smart selection of high-impact configuration parameters of the given tuning objective. Finally, it uses a novel Reinforcement Learning (RL)-driven early stopping mechanism to balance the cost and performance gain. Experimental results show that TunIO leads to a reduction of up to \u2248 73% in tuning time while achieving the same performance gain when compared to H5Tuner. It achieves a significant performance gain/cost of 208.4 MBps/min (I/O bandwidth for each minute spent in tuning) over existing approaches under our testing. Index Terms-AI-powered I/O tuning, storage stack tuning, autotun- ing, source code transformations, and I/O performance optimization","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/rajesh-2024-tunio-05a8.pdf"},"tags":["AI for I/O","I/O Stack Tuning"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2022luxio","slug":"bateman-2022-luxio-2487","title":"LuxIO: Intelligent Resource Provisioning and Auto-Configuration for Storage Services","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","J. Ye","S. Herbein","A. Kougkas","X.-H. Sun"],"venue":"The 29th edition of the IEEE International Conference on High Performance Computing, Data, and Analytics (HiPC\'22)","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/hipc56025.2022.00041","abstract":"Abstract-Storage in HPC is typically a single Remote and Static Storage (RSS) resource. However, applications demonstrate diverse I/O requirements that can be better served by a multi-storage approach. Cur- rent practice employs ephemeral storage systems running on either node- local or shared storage resources. Yet, the burden of provisioning and configuring intermediate storage falls solely on the users, while global job schedulers offer little to no support for custom deployments. This lack of support often leads to over- or under-provisioning of resources and poorly configured storage systems. To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service. LuxIO constructs storage deployments configured to best match I/O require- ments. LuxIO-tuned storage services show performance improvements up to 2x across common applications and benchmarks, while introducing minimal overhead of 93.40 ms on top of existing job scheduling pipelines. LuxIO improves resource utilization by up to 25% in select workflows.","hasAbstract":true,"lede":"To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service.","links":{"pdf":"https://grc.iit.edu/papers/2022/bateman-2022-luxio-2487.pdf"},"tags":["Resource Provisioning","I/O Behavior","Storage Auto-Tuning","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2021hflow","slug":"cernuda-2021-hflow-2f5b","title":"HFlow: A Dynamic and Elastic Multi-Layered Data Forwarder","authors":["J. Cernuda","H. Devarajan","L. Logan","K. Bateman","N. Rajesh","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Conference","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00064","abstract":"Modern applications are highly data-intensive, leading to the well-known I/O bottleneck problem. Scientists have proposed the placement of fast intermediate storage resources which aim to mask the I/O penalties. To manage these resources, three core software abstractions are being used in leadership-class computing facilities: IO Forwarders, Burst Buffers, and Data Stagers. Yet, with the rise of multi-tenant deployment in HPC systems, these software abstractions are: managed and maintained in isolation, leading to inefficient interactions; allocated statically, leading to load imbalance; exclusively bifurcated between the intermediate storage, leading to under-utilization of resources, and, in many cases, do not support in-situ operations. To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm. HFlow introduces a unified data movement abstraction (the ByteFlow) providing data-independent tasks that can be executed anywhere and thus, enabling dynamic resource provisioning. Moreover, the processing elements executing the ByteFlows are designed to be ephemeral and, hence, enable elastic management of intermediate storage resources. Our results show that applications running under HFlow display an increase in performance of 3x when compared with state-of-the-art software solutions. Index Terms-Data streaming, I/O forwarding, elasticity, dynamicity, multi-tenant, data-intensive, I/O,data pipeline, in-transit","hasAbstract":true,"lede":"To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm.","links":{"pdf":"https://grc.iit.edu/papers/2021/cernuda-2021-hflow-2f5b.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021apollo","slug":"rajesh-2021-apollo-dbd8","title":"Apollo: An ML-assisted Real-Time Storage Resource Observer","authors":["N. Rajesh","H. Devarajan","J. Cernuda","K. Bateman","L. Logan","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 30th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'21), June 21-25, 2021","type":"Conference","entryType":"inproceedings","date":"June, 2021","year":2021,"era":"iit","month":6,"doi":"10.1145/3431379.3460640","abstract":"Applications and middleware services, such as data placement en- gines, I/O scheduling, and prefetching engines, require low-latency access to telemetry data in order to make optimal decisions. However, typical monitoring services store their telemetry data in a database in order to allow applications to query them, resulting in significant latency penalties. This work presents Apollo: a low-latency mon- itoring service that aims to provide applications and middleware libraries with direct access to relational telemetry data. Monitoring the system can create interference and overhead, slowing down raw performance of the resources for the job. However, having a current view of the system can aid middleware services in making more optimal decisions which can ultimately improve the overall perfor- mance. Apollo has been designed from the ground up to provide low latency, using Publish\u2013Subscribe (Pub-Sub) semantics, and low overhead, using adaptive intervals in order to change the length of time between polling the resource for telemetry data and machine learning in order to predict changes to the telemetry data between actual resource polling. This work also provides some high level abstractions called I/O curators, which can further aid middleware libraries and applications to make optimal decisions. Evaluations showcase that Apollo can achieve sub-millisecond latency for acquir- ing complex insights with a memory overhead of 57MB and CPU overhead being only 7% more than existing state-of-the-art systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-apollo-dbd8.pdf"},"tags":["HPC","Machine Learning","Resource Monitoring","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020chronolog","slug":"kougkas-2020-chronolog-c458","title":"ChronoLog: A Distributed Shared Tiered Log Store with Time-based Data Ordering","authors":["A. Kougkas","H. Devarajan","K. Bateman","J. Cernuda","N. Rajesh","X.-H. Sun"],"venue":"The 36th International Conference on Massive Storage Systems and Technology (MSST\'20), Oct. 29-30, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"abstract":"Modern applications produce and process massive amounts of activity (or log) data. Traditional storage systems were not designed with an append-only data model and a new storage abstraction aims to fill this gap: the distributed shared log store. However, existing solutions struggle to provide a scalable, parallel, and high-performance solution that can support a diverse set of conflicting log workload requirements. Finding the tail of a distributed log is a centralized point of contention. In this paper, we show how using physical time can help alleviate the need of centralized synchronization points. We present ChronoLog, a new, distributed, shared, and multi-tiered log store that can handle more than a million tail operations per second. Evaluation results show ChronoLog\'s potential, outperforming existing solution by an order of magnitude.","hasAbstract":true,"lede":"We show how using physical time can help alleviate the need of centralized synchronization points.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-chronolog-c458.pdf"},"tags":["Distributed Log","Shared Log","Tiered Storage","ChronoLog"],"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcl","slug":"devarajan-2020-hcl-d2f4","title":"HCL: Distributing Parallel Data Structures in Extreme Scales","authors":["H. Devarajan","A. Kougkas","K. Bateman","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing (CLUSTER\'20), Sept. 14-17, 2020","type":"Conference","entryType":"inproceedings","date":"September, 2020","year":2020,"era":"iit","month":9,"doi":"10.1109/cluster49012.2020.00035","abstract":"Most parallel programs use irregular control flow and data structures, which are perfect for one-sided communication paradigms such as MPI or PGAS programming languages. However, these environments lack the presence of efficient function-based application libraries that can utilize popular communication fabrics such as TCP, Infinity Band (IB), and RDMA over Converged Ethernet (RoCE). Additionally, there is a lack of high-performance data structure interfaces. We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues. HCL uses a RPC over RDMA technology that implements a novel procedural programming paradigm. In this paper, we argue a RPC over RDMA technology can serve as a high-performance, flexible, and co-ordination free backend for implementing complex data structures. Evaluation results from testing real workloads shows that HCL programs are 2x to 12x faster compared to BCL, a state-of-the-art distributed data structure library.","hasAbstract":true,"lede":"We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4-slides.pdf"},"tags":["Distributed Data Structure","RPC over RDMA","Hybrid Data Access Model","HPC Data Containers","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);